package controlplane

// Version registration belongs to the shared schema/restore entry points.
const migrationSessionSchema = `
CREATE TABLE v3_migration_sessions(id text PRIMARY KEY,version bigint NOT NULL DEFAULT 1,recovery_hold boolean NOT NULL DEFAULT false,roles jsonb NOT NULL,phase text NOT NULL DEFAULT 'collecting' CHECK(phase IN ('collecting','indexed','frozen','reconciled')),freeze_digest text NOT NULL DEFAULT '',freeze_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE v3_migration_revisions(id text PRIMARY KEY,session text NOT NULL REFERENCES v3_migration_sessions(id),role text NOT NULL,source_id text NOT NULL,snapshot text NOT NULL,snapshot_sha256 text NOT NULL,sequence bigint NOT NULL,request_version bigint NOT NULL,finished_version bigint NOT NULL DEFAULT 0,state text NOT NULL DEFAULT 'indexing' CHECK(state IN ('indexing','ready')),cursor_table text NOT NULL DEFAULT '',cursor_key bigint,cursor_done boolean NOT NULL DEFAULT false,records bigint NOT NULL DEFAULT 0,index_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(session,role,snapshot_sha256),UNIQUE(session,role,sequence));
CREATE UNIQUE INDEX v3_migration_revision_running ON v3_migration_revisions(session) WHERE state='indexing';
CREATE TABLE v3_migration_revision_tables(revision text NOT NULL REFERENCES v3_migration_revisions(id),table_name text NOT NULL,records bigint NOT NULL,schema_digest text NOT NULL,PRIMARY KEY(revision,table_name));
CREATE TABLE v3_migration_revision_rows(revision text NOT NULL REFERENCES v3_migration_revisions(id),table_name text NOT NULL,record_key bigint NOT NULL,digest text NOT NULL,PRIMARY KEY(revision,table_name,record_key));
CREATE TABLE v3_migration_deltas(id text PRIMARY KEY,session text NOT NULL REFERENCES v3_migration_sessions(id),base text NOT NULL REFERENCES v3_migration_revisions(id),target text NOT NULL REFERENCES v3_migration_revisions(id),request_version bigint NOT NULL,finished_version bigint NOT NULL DEFAULT 0,state text NOT NULL DEFAULT 'comparing' CHECK(state IN ('comparing','ready')),cursor_table text NOT NULL DEFAULT '',cursor_key bigint,added bigint NOT NULL DEFAULT 0,modified bigint NOT NULL DEFAULT 0,deleted bigint NOT NULL DEFAULT 0,unchanged bigint NOT NULL DEFAULT 0,schema_changes bigint NOT NULL DEFAULT 0,digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(session,base,target));
CREATE UNIQUE INDEX v3_migration_delta_running ON v3_migration_deltas(session) WHERE state='comparing';
CREATE TABLE v3_migration_delta_rows(delta text NOT NULL REFERENCES v3_migration_deltas(id),table_name text NOT NULL,record_key bigint NOT NULL,operation text NOT NULL CHECK(operation IN ('ADD','UPDATE','DELETE','UNCHANGED')),before_digest text NOT NULL,after_digest text NOT NULL,PRIMARY KEY(delta,table_name,record_key));
CREATE TABLE v3_migration_freezes(session text NOT NULL REFERENCES v3_migration_sessions(id),role text NOT NULL,revision text NOT NULL REFERENCES v3_migration_revisions(id),manifest_digest text NOT NULL,evidence_digest text NOT NULL,request_version bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(session,role));
CREATE TABLE v3_migration_reconciliations(id text PRIMARY KEY,session text NOT NULL REFERENCES v3_migration_sessions(id),session_version bigint NOT NULL,report jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
`
